func loadConfig() (config, error) {
    cfg := config{}
    name := ""
    if _, err := os.Stat(".wrapcheck.yaml"); err == nil {
        name = ".wrapcheck.yaml"
    } else if _, err := os.Stat(".wrapcheck.yml"); err == nil {
        name = ".wrapcheck.yml"
    }
    if name != "" {
        data, err := os.ReadFile(name)
        if err != nil {
            log.Fatalf("failed to parse config: %v", err)
        }
        if err := parseSimpleYAML(data, &cfg); err != nil {
            log.Fatalf("failed to parse config: While parsing config: %v", err)
        }
    }
    if !cfg.ignoreSigsSet {
        cfg.ignoreSigs = append([]string{}, defaultIgnoreSigs...)
    }
    cfg.ignoreSigs = append(cfg.ignoreSigs, cfg.extraIgnoreSigs...)

    for _, pat := range cfg.ignoreSigRegexps {
        re, err := regexp.Compile(pat)
        if err != nil {
            fmt.Fprintf(os.Stderr, "wrapcheck: unable to compile regexp %s: %v\n\n", pat, err)
            return cfg, err
        }
        cfg.sigRegexps = append(cfg.sigRegexps, re)
    }
    for _, pat := range cfg.ignoreInterfaceRegexps {
        re, err := regexp.Compile(pat)
        if err != nil {
            fmt.Fprintf(os.Stderr, "wrapcheck: unable to compile regexp %s: %v\n\n", pat, err)
            return cfg, err
        }
        cfg.ifaceRegexps = append(cfg.ifaceRegexps, re)
    }
    for _, glob := range cfg.ignorePackageGlobs {
        if _, err := path.Match(glob, ""); err != nil {
            fmt.Fprintf(os.Stderr, "wrapcheck: unable to compile globs %%!s(<nil>): %v\n\n", err)
            return cfg, err
        }
    }
    return cfg, nil
}

func parseSimpleYAML(data []byte, cfg *config) error {
    lines := strings.Split(string(data), "\n")
    var current string
    for _, raw := range lines {
        line := stripComment(raw)
        if strings.TrimSpace(line) == "" {
            continue
        }
        trimmed := strings.TrimSpace(line)
        if strings.HasPrefix(trimmed, "-") {
            if current == "" {
                return fmt.Errorf("yaml: did not find expected key")
            }
            val := strings.TrimSpace(strings.TrimPrefix(trimmed, "-"))
            val = unquoteYAML(val)
            addConfigListValue(cfg, current, val)
            continue
        }
        idx := strings.Index(trimmed, ":")
        if idx <= 0 {
            return fmt.Errorf("yaml: did not find expected key")
        }
        key := strings.TrimSpace(trimmed[:idx])
        val := strings.TrimSpace(trimmed[idx+1:])
        current = ""
        switch key {
        case "ignoreSigs", "extraIgnoreSigs", "ignoreSigRegexps", "ignorePackageGlobs", "ignoreInterfaceRegexps":
            current = key
            if val != "" {
                vals, err := parseYAMLListValue(val)
                if err != nil {
                    return err
                }
                if key == "ignoreSigs" {
                    cfg.ignoreSigsSet = true
                    cfg.ignoreSigs = nil
                }
                for _, v := range vals {
                    addConfigListValue(cfg, key, v)
                }
            } else if key == "ignoreSigs" {
                cfg.ignoreSigsSet = true
                cfg.ignoreSigs = nil
            }
        case "reportInternalErrors":
            if val == "" {
                return fmt.Errorf("yaml: did not find expected key")
            }
            b, err := strconv.ParseBool(unquoteYAML(val))
            if err != nil {
                log.Fatalf("failed to unmarshal config: 1 error(s) decoding:\n\n* cannot parse 'reportInternalErrors' as bool: %v", err)
            }
            cfg.reportInternalErrors = b
        default:
            // Unknown keys are ignored by the original decoder.
        }
    }
    return nil
}

func stripComment(s string) string {
    inSingle, inDouble := false, false
    for i, r := range s {
        switch r {
        case '\'':
            if !inDouble {
                inSingle = !inSingle
            }
        case '"':
            if !inSingle {
                inDouble = !inDouble
            }
        case '#':
            if !inSingle && !inDouble {
                return s[:i]
            }
        }
    }
    return s
}

func parseYAMLListValue(v string) ([]string, error) {
    v = strings.TrimSpace(v)
    if v == "[]" {
        return nil, nil
    }
    if strings.HasPrefix(v, "[") && strings.HasSuffix(v, "]") {
        inner := strings.TrimSpace(v[1 : len(v)-1])
        if inner == "" {
            return nil, nil
        }
        var out []string
        var cur strings.Builder
        inSingle, inDouble := false, false
        for _, r := range inner {
            switch r {
            case '\'':
                if !inDouble {
                    inSingle = !inSingle
                }
                cur.WriteRune(r)
            case '"':
                if !inSingle {
                    inDouble = !inDouble
                }
                cur.WriteRune(r)
            case ',':
                if !inSingle && !inDouble {
                    out = append(out, unquoteYAML(strings.TrimSpace(cur.String())))
                    cur.Reset()
                } else {
                    cur.WriteRune(r)
                }
            default:
                cur.WriteRune(r)
            }
        }
        out = append(out, unquoteYAML(strings.TrimSpace(cur.String())))
        return out, nil
    }
    return []string{unquoteYAML(v)}, nil
}

func unquoteYAML(v string) string {
    v = strings.TrimSpace(v)
    if len(v) >= 2 {
        if (v[0] == '"' && v[len(v)-1] == '"') || (v[0] == '\'' && v[len(v)-1] == '\'') {
            if u, err := strconv.Unquote(v); err == nil {
                return u
            }
            return v[1 : len(v)-1]
        }
    }
    return v
}

func addConfigListValue(cfg *config, key, val string) {
    switch key {
    case "ignoreSigs":
        if !cfg.ignoreSigsSet {
            cfg.ignoreSigsSet = true
            cfg.ignoreSigs = nil
        }
        cfg.ignoreSigs = append(cfg.ignoreSigs, val)
    case "extraIgnoreSigs":
        cfg.extraIgnoreSigs = append(cfg.extraIgnoreSigs, val)
    case "ignoreSigRegexps":
        cfg.ignoreSigRegexps = append(cfg.ignoreSigRegexps, val)
    case "ignorePackageGlobs":
        cfg.ignorePackageGlobs = append(cfg.ignorePackageGlobs, val)
    case "ignoreInterfaceRegexps":
        cfg.ignoreInterfaceRegexps = append(cfg.ignoreInterfaceRegexps, val)
    }
}

type loadError struct {
    pkg goPackage
    err goPackageError
}

func loadPackages(patterns []string, includeTests bool) ([]goPackage, map[string]string, []loadError, error) {
    args := []string{"list", "-e", "-export", "-deps", "-json"}
    if includeTests {
        args = append(args, "-test")
    }
    args = append(args, patterns...)
    cmd := exec.Command("go", args...)
    out, err := cmd.CombinedOutput()
    if len(out) == 0 && err != nil {
        return nil, nil, nil, err
    }

    dec := json.NewDecoder(bytes.NewReader(out))
    exports := map[string]string{}
    var roots []goPackage
    var loadErrs []loadError
    seenRoot := map[string]bool{}
    for {
        var gp goPackage
        if e := dec.Decode(&gp); e != nil {
            if e == io.EOF {
                break
            }
            return nil, nil, nil, e
        }
        if gp.Export != "" {
            exports[gp.ImportPath] = gp.Export
            base := baseImportPath(gp.ImportPath)
            if base != gp.ImportPath && exports[base] == "" {
                exports[base] = gp.Export
            }
        }
        if gp.DepOnly {
            continue
        }
        if isTestMainPackage(gp) {
            continue
        }
        if seenRoot[gp.ImportPath] {
            continue
        }
        seenRoot[gp.ImportPath] = true
        if gp.Error != nil {
            loadErrs = append(loadErrs, loadError{pkg: gp, err: *gp.Error})
        } else {
            roots = append(roots, gp)
        }
    }
    return roots, exports, loadErrs, err
}

func isTestMainPackage(gp goPackage) bool {
    return gp.ForTest == "" && strings.HasSuffix(gp.ImportPath, ".test") && gp.Name == "main"
}

func packageJSONID(gp goPackage) string { return gp.ImportPath }

func baseImportPath(p string) string {
    if i := strings.Index(p, " ["); i >= 0 {
        return p[:i]
    }
    return p
}

func analyzePackage(gp goPackage, exports map[string]string, cfg config) ([]diagnostic, []string) {
    fset := token.NewFileSet()
    var files []*ast.File
    var typeErrs []string
    filenames := append([]string{}, gp.GoFiles...)
    filenames = append(filenames, gp.CgoFiles...)
    for _, gf := range filenames {
        filename := gf
        if !filepath.IsAbs(filename) {
            filename = filepath.Join(gp.Dir, gf)
        }
        f, err := parser.ParseFile(fset, filename, nil, parser.ParseComments)
        if err != nil {
            typeErrs = append(typeErrs, err.Error())
            continue
        }
        files = append(files, f)
    }
    if len(files) == 0 {
        return nil, typeErrs
    }

    importerLookup := func(importPath string) (io.ReadCloser, error) {
        if p := exports[importPath]; p != "" {
            return os.Open(p)
        }
        return nil, fmt.Errorf("can't find import: %s", importPath)
    }
    imp := importer.ForCompiler(fset, "gc", importerLookup)
    info := &types.Info{
        Types:      map[ast.Expr]types.TypeAndValue{},
        Defs:       map[*ast.Ident]types.Object{},
        Uses:       map[*ast.Ident]types.Object{},
        Selections: map[*ast.SelectorExpr]*types.Selection{},
    }
    conf := types.Config{
        Importer: imp,
        Error: func(err error) {
            typeErrs = append(typeErrs, err.Error())
        },
    }
    pkgPath := baseImportPath(gp.ImportPath)
    pkg, err := conf.Check(pkgPath, fset, files, info)
    if err != nil && len(typeErrs) == 0 {
        typeErrs = append(typeErrs, err.Error())
    }
    if len(typeErrs) > 0 {
        return nil, typeErrs
    }

    analyzer := &pkgAnalyzer{
        fset:    fset,
        info:    info,
        pkg:     pkg,
        cfg:     cfg,
        sources: map[types.Object]sourceInfo{},
    }
    for _, f := range files {
        analyzer.file = f
        ast.Inspect(f, analyzer.inspect)
    }
    return analyzer.diags, nil
}

type pkgAnalyzer struct {
    fset    *token.FileSet
    info    *types.Info
    pkg     *types.Package
    cfg     config
    sources map[types.Object]sourceInfo
    diags   []diagnostic
    file    *ast.File
}

func (a *pkgAnalyzer) inspect(n ast.Node) bool {
    switch x := n.(type) {
    case *ast.AssignStmt:
        a.handleAssign(x.Lhs, x.Rhs)
    case *ast.ValueSpec:
        lhs := make([]ast.Expr, 0, len(x.Names))
        for _, name := range x.Names {
            lhs = append(lhs, name)
        }
        a.handleAssign(lhs, x.Values)
    case *ast.ReturnStmt:
        a.handleReturn(x)
    }
    return true
}

func (a *pkgAnalyzer) handleAssign(lhs []ast.Expr, rhs []ast.Expr) {
    var src *sourceInfo
    if len(rhs) > 0 {
        if call, ok := rhs[0].(*ast.CallExpr); ok {
            if s, yes := a.classifyCall(call, false); yes {
                src = &s
            }
        }
    }
    for _, le := range lhs {
        id, ok := le.(*ast.Ident)
        if !ok || id.Name == "_" {
            continue
        }
        obj := a.info.Defs[id]
        if obj == nil {
            obj = a.info.Uses[id]
        }
        if obj == nil || !isExactError(obj.Type()) {
            continue
        }
        if src != nil {
            a.sources[obj] = *src
        } else {
            delete(a.sources, obj)
        }
    }
}

func (a *pkgAnalyzer) handleReturn(ret *ast.ReturnStmt) {
    if len(ret.Results) == 0 {
        return
    }
    for _, expr := range ret.Results {
        switch e := expr.(type) {
        case *ast.Ident:
            obj := a.info.Uses[e]
            if obj == nil {
                obj = a.info.Defs[e]
            }
            if obj == nil || !isExactError(obj.Type()) {
                continue
            }
            if src, ok := a.sources[obj]; ok {
                a.addDiag(e.Pos(), src)
            }
        case *ast.CallExpr:
            if src, ok := a.classifyCall(e, true); ok {
                a.addDiag(e.Pos(), src)
            }
            return
        default:
            // Other expressions do not participate in wrapcheck's simple tracking.
        }
    }
}

func (a *pkgAnalyzer) classifyCall(call *ast.CallExpr, requireErrorResult bool) (sourceInfo, bool) {
    obj, isIface, ifaceName := a.callObject(call)
    if obj == nil {
        return sourceInfo{}, false
    }
    sig := types.ObjectString(obj, nil)

    if requireErrorResult && !callReturnsExactError(obj) {
        return sourceInfo{}, false
    }
    if a.ignoredSignature(sig) {
        return sourceInfo{}, false
    }

    objPkg := obj.Pkg()
    if a.ignoredPackage(objPkg) {
        return sourceInfo{}, false
    }

    if isIface && !a.ignoredInterfaceName(ifaceName) {
        return sourceInfo{sig: sig, kind: "interface"}, true
    }

    if objPkg == nil {
        return sourceInfo{}, false
    }
    if objPkg.Path() == a.pkg.Path() {
        if a.cfg.reportInternalErrors {
            return sourceInfo{sig: sig, kind: "internal"}, true
        }
        return sourceInfo{}, false
    }
    return sourceInfo{sig: sig, kind: "external"}, true
}

func (a *pkgAnalyzer) callObject(call *ast.CallExpr) (types.Object, bool, string) {
    switch fun := call.Fun.(type) {
    case *ast.SelectorExpr:
        if sel := a.info.Selections[fun]; sel != nil {
            obj := sel.Obj()
            iface := isInterfaceType(sel.Recv())
            name := interfaceName(sel.Recv())
            if name == "" {
                name = receiverNameFromObject(obj)
            }
            return obj, iface, name
        }
        if obj := a.info.Uses[fun.Sel]; obj != nil {
            return obj, false, ""
        }
    case *ast.Ident:
        if obj := a.info.Uses[fun]; obj != nil {
            return obj, false, ""
        }
        if obj := a.info.Defs[fun]; obj != nil {
            return obj, false, ""
        }
    case *ast.IndexExpr:
        // Generic function instantiation, e.g. f[int]().
        if id, ok := fun.X.(*ast.Ident); ok {
            if obj := a.info.Uses[id]; obj != nil {
                return obj, false, ""
            }
        }
        if sel, ok := fun.X.(*ast.SelectorExpr); ok {
            if s := a.info.Selections[sel]; s != nil {
                obj := s.Obj()
                iface := isInterfaceType(s.Recv())
                name := interfaceName(s.Recv())
                if name == "" {
                    name = receiverNameFromObject(obj)
                }
                return obj, iface, name
            }
            if obj := a.info.Uses[sel.Sel]; obj != nil {
                return obj, false, ""
            }
        }
    case *ast.IndexListExpr:
        if sel, ok := fun.X.(*ast.SelectorExpr); ok {
            if obj := a.info.Uses[sel.Sel]; obj != nil {
                return obj, false, ""
            }
        }
        if id, ok := fun.X.(*ast.Ident); ok {
            if obj := a.info.Uses[id]; obj != nil {
                return obj, false, ""
            }
        }
    }
    return nil, false, ""
}

func isInterfaceType(t types.Type) bool {
    if t == nil {
        return false
    }
    _, ok := t.Underlying().(*types.Interface)
    return ok
}

func interfaceName(t types.Type) string {
    switch tt := t.(type) {
    case *types.Named:
        if tt.Obj() != nil {
            return tt.Obj().Name()
        }
    case *types.Pointer:
        return interfaceName(tt.Elem())
    }
    return ""
}

func receiverNameFromObject(obj types.Object) string {
    fn, ok := obj.(*types.Func)
    if !ok {
        return ""
    }
    sig, ok := fn.Type().(*types.Signature)
    if !ok || sig.Recv() == nil {
        return ""
    }
    return interfaceName(sig.Recv().Type())
}

func callReturnsExactError(obj types.Object) bool {
    sig, ok := obj.Type().(*types.Signature)
    if !ok {
        return false
    }
    res := sig.Results()
    for i := 0; i < res.Len(); i++ {
        if isExactError(res.At(i).Type()) {
            return true
        }
    }
    return false
}

func isExactError(t types.Type) bool {
    if t == nil {
        return false
    }
    return types.Identical(t, errType)
}

func (a *pkgAnalyzer) ignoredSignature(sig string) bool {
    for _, ign := range a.cfg.ignoreSigs {
        if ign != "" && strings.Contains(sig, ign) {
            return true
        }
    }
    for _, re := range a.cfg.sigRegexps {
        if re.MatchString(sig) {
            return true
        }
    }
    return false
}

func (a *pkgAnalyzer) ignoredPackage(pkg *types.Package) bool {
    if pkg == nil {
        return false
    }
    p := pkg.Path()
    for _, glob := range a.cfg.ignorePackageGlobs {
        if ok, _ := path.Match(glob, p); ok {
            return true
        }
    }
    return false
}

func (a *pkgAnalyzer) ignoredInterfaceName(name string) bool {
    if name == "" {
        name = "interface"
    }
    for _, re := range a.cfg.ifaceRegexps {
        if re.MatchString(name) {
            return true
        }
    }
    return false
}

func (a *pkgAnalyzer) addDiag(pos token.Pos, src sourceInfo) {
    p := a.fset.Position(pos)
    msg := ""
    switch src.kind {
    case "interface":
        msg = "error returned from interface method should be wrapped: sig: " + src.sig
    case "internal":
        msg = "package-internal error should be wrapped: sig: " + src.sig
    default:
        msg = "error returned from external package is unwrapped: sig: " + src.sig
    }
    a.diags = append(a.diags, diagnostic{
        Posn:    fmt.Sprintf("%s:%d:%d", p.Filename, p.Line, p.Column),
        Message: msg,
        File:    p.Filename,
        Line:    p.Line,
        Col:     p.Column,
    })
}

func printPackageError(w io.Writer, importPath string, pe goPackageError) {
    pos := pe.Pos
    if pos == "" {
        pos = "-"
    }
    fmt.Fprintf(w, "%s: %s\n", pos, pe.Err)
    fmt.Fprintln(w, "wrapcheck: analysis skipped due to errors in package")
}

func emitJSON(results []pkgResult) {
    out := map[string]interface{}{}
    for _, r := range results {
        if r.Err != "" {
            out[r.ID] = map[string]interface{}{analyzerName: map[string]string{"error": r.Err}}
            continue
        }
        if len(r.Diags) == 0 {
            continue
        }
        jds := make([]jsonDiag, 0, len(r.Diags))
        for _, d := range r.Diags {
            jds = append(jds, jsonDiag{Posn: d.Posn, Message: d.Message})
        }
        out[r.ID] = map[string]interface{}{analyzerName: jds}
    }
    b, _ := json.MarshalIndent(out, "", "\t")
    os.Stdout.Write(b)
    os.Stdout.Write([]byte("\n"))
}

func printContext(w io.Writer, filename string, line, ctx int) {
    data, err := os.ReadFile(filename)
    if err != nil {
        return
    }
    lines := strings.SplitAfter(string(data), "\n")
    if len(lines) > 0 && lines[len(lines)-1] == "" {
        lines = lines[:len(lines)-1]
    }
    start := line - ctx
    if start < 1 {
        start = 1
    }
    end := line + ctx
    if end > len(lines) {
        end = len(lines)
    }
    for i := start; i <= end; i++ {
        text := strings.TrimSuffix(lines[i-1], "\n")
        text = strings.TrimSuffix(text, "\r")
        fmt.Fprintf(w, "%d\t%s\n", i, text)
    }
}

func printTraceHint(trace string) {
    if trace == "" {
        return
    }
    _ = os.WriteFile(trace, nil, 0644)
    fmt.Fprintln(os.Stderr, "wrapcheck: To view the trace, run:")
    fmt.Fprintf(os.Stderr, "$ go tool trace view %s\n", trace)
}

