const analyzerName = "wrapcheck"
const analyzerDoc = "Checks that errors returned from external packages are wrapped"

var defaultIgnoreSigs = []string{
    ".Errorf(",
    "errors.New(",
    "errors.Unwrap(",
    "errors.Join(",
    ".Wrap(",
    ".Wrapf(",
    ".WithMessage(",
