type options struct {
    all        bool
    context    int
    cpuProfile string
    debug      string
    diff       bool
    fix        bool
    flags      bool
    json       bool
    memProfile string
    source     bool
    tags       string
    test       bool
    trace      string
    verbose    bool
}

type config struct {
    ignoreSigs             []string
    extraIgnoreSigs        []string
    ignoreSigRegexps       []string
    ignorePackageGlobs     []string
    ignoreInterfaceRegexps []string
    reportInternalErrors   bool

    ignoreSigsSet bool
    sigRegexps    []*regexp.Regexp
    ifaceRegexps  []*regexp.Regexp
}

type goPackage struct {
    ImportPath   string          `json:"ImportPath"`
    Name         string          `json:"Name"`
    Dir          string          `json:"Dir"`
    GoFiles      []string        `json:"GoFiles"`
    CgoFiles     []string        `json:"CgoFiles"`
    Export       string          `json:"Export"`
    ForTest      string          `json:"ForTest"`
    DepOnly      bool            `json:"DepOnly"`
    Incomplete   bool            `json:"Incomplete"`
    Error        *goPackageError `json:"Error"`
    DepsErrors   []goPackageError `json:"DepsErrors"`
}

type goPackageError struct {
    ImportStack []string `json:"ImportStack"`
    Pos         string   `json:"Pos"`
    Err         string   `json:"Err"`
}

type sourceInfo struct {
    sig  string
    kind string
}

type diagnostic struct {
    Posn    string
    Message string
    File    string
    Line    int
    Col     int
}

type pkgResult struct {
    ID    string
    Diags []diagnostic
    Err   string
}

type jsonDiag struct {
    Posn    string `json:"posn"`
    Message string `json:"message"`
}

func main() {
    handleVersionFlag(os.Args[1:])

    opt, patterns, parseCode := parseFlags(os.Args[1:])
    if parseCode >= 0 {
        os.Exit(parseCode)
    }

    if opt.flags {
        printFlagsJSON()
        return
    }

    if len(patterns) == 0 {
        usage(os.Stderr)
        os.Exit(1)
    }

    cfg, err := loadConfig()
    if err != nil {
        // loadConfig prints errors whose format comes from the original's logger.
        os.Exit(1)
    }

    if opt.fix {
        // The analyzer provides no fixes. The original driver suppresses diagnostics under -fix.
        if opt.trace != "" {
            printTraceHint(opt.trace)
        }
        return
    }

    pkgs, exports, loadErrs, listErr := loadPackages(patterns, opt.test)
    if listErr != nil && len(pkgs) == 0 && len(loadErrs) == 0 {
        // Match the common go/packages message for a direct package that matches nothing.
        if len(patterns) > 0 {
            fmt.Fprintf(os.Stderr, "wrapcheck: %s matched no packages\n", patterns[0])
        } else {
            fmt.Fprintf(os.Stderr, "wrapcheck: %v\n", listErr)
        }
        os.Exit(1)
    }

    var results []pkgResult
    hadLoadError := false

    for _, le := range loadErrs {
        hadLoadError = true
        printPackageError(os.Stderr, le.pkg.ImportPath, le.err)
        results = append(results, pkgResult{ID: packageJSONID(le.pkg), Err: "analysis skipped due to errors in package"})
    }

    for _, gp := range pkgs {
        if gp.Error != nil {
            hadLoadError = true
            printPackageError(os.Stderr, gp.ImportPath, *gp.Error)
            results = append(results, pkgResult{ID: packageJSONID(gp), Err: "analysis skipped due to errors in package"})
            continue
        }
        if len(gp.GoFiles) == 0 && len(gp.CgoFiles) == 0 {
            continue
        }
        diags, errs := analyzePackage(gp, exports, cfg)
        if len(errs) > 0 {
            hadLoadError = true
            for _, e := range errs {
                fmt.Fprintln(os.Stderr, e)
            }
            fmt.Fprintln(os.Stderr, "wrapcheck: analysis skipped due to errors in package")
            results = append(results, pkgResult{ID: packageJSONID(gp), Err: "analysis skipped due to errors in package"})
            continue
        }
        if len(diags) > 0 || opt.json {
            results = append(results, pkgResult{ID: packageJSONID(gp), Diags: diags})
        }
    }

    if opt.json {
        emitJSON(results)
        if hadLoadError {
            os.Exit(1)
        }
        return
    }

    seen := map[string]bool{}
    hadDiag := false
    for _, r := range results {
        if r.Err != "" {
            if !hadLoadError { // normally already printed above
                fmt.Fprintln(os.Stderr, "wrapcheck: "+r.Err)
            }
            continue
        }
        for _, d := range r.Diags {
            key := d.Posn + "\x00" + d.Message
            if seen[key] {
                continue
            }
            seen[key] = true
            hadDiag = true
            fmt.Fprintf(os.Stderr, "%s: %s\n", d.Posn, d.Message)
            if opt.context >= 0 {
                printContext(os.Stderr, d.File, d.Line, opt.context)
            }
        }
    }

    if opt.trace != "" {
        printTraceHint(opt.trace)
    }

    if hadLoadError {
        os.Exit(1)
    }
    if hadDiag {
        os.Exit(3)
    }
}

func handleVersionFlag(args []string) {
    for i, a := range args {
        if a == "--" {
            return
        }
        if a == "-V" || a == "--V" {
            fmt.Fprintln(os.Stderr, "wrapcheck: unsupported flag value: -V=true (use -V=full)")
            os.Exit(1)
        }
        if strings.HasPrefix(a, "-V=") || strings.HasPrefix(a, "--V=") {
            val := strings.TrimPrefix(strings.TrimPrefix(a, "--V="), "-V=")
            if val != "full" {
                fmt.Fprintf(os.Stderr, "wrapcheck: unsupported flag value: -V=%s (use -V=full)\n", val)
                os.Exit(1)
            }
            exe, _ := os.Executable()
            if exe == "" {
                exe = os.Args[0]
            }
            if _, err := os.Open(exe); err != nil {
                fmt.Fprintf(os.Stderr, "wrapcheck: %v\n", err)
                os.Exit(1)
            }
            // If the file is readable (unusual for this benchmark), provide a compact substitute.
            fmt.Fprintln(os.Stderr, "wrapcheck: (devel)")
            os.Exit(0)
        }
        if a == "-Vfull" && i >= 0 { // flag package would not accept this spelling; leave it alone.
            return
        }
    }
}

func parseFlags(args []string) (options, []string, int) {
    opt := options{context: -1, test: true}
    fs := flag.NewFlagSet("wrapcheck", flag.ContinueOnError)
    fs.SetOutput(os.Stderr)
    fs.Usage = func() { usage(os.Stderr) }
    fs.BoolVar(&opt.all, "all", false, "no effect (deprecated)")
    fs.IntVar(&opt.context, "c", -1, "display offending line with this many lines of context")
    fs.StringVar(&opt.cpuProfile, "cpuprofile", "", "write CPU profile to this file")
    fs.StringVar(&opt.debug, "debug", "", "debug flags, any subset of \"fpstv\"")
    fs.BoolVar(&opt.diff, "diff", false, "with -fix, don't update the files, but print a unified diff")
    fs.BoolVar(&opt.fix, "fix", false, "apply all suggested fixes")
    fs.BoolVar(&opt.flags, "flags", false, "print analyzer flags in JSON")
    fs.BoolVar(&opt.json, "json", false, "emit JSON output")
    fs.StringVar(&opt.memProfile, "memprofile", "", "write memory profile to this file")
    fs.BoolVar(&opt.source, "source", false, "no effect (deprecated)")
    fs.StringVar(&opt.tags, "tags", "", "no effect (deprecated)")
    fs.BoolVar(&opt.test, "test", true, "indicates whether test files should be analyzed, too")
    fs.StringVar(&opt.trace, "trace", "", "write trace log to this file")
    fs.BoolVar(&opt.verbose, "v", false, "no effect (deprecated)")

    if err := fs.Parse(args); err != nil {
        if errors.Is(err, flag.ErrHelp) {
            return opt, nil, 0
        }
        return opt, nil, 2
    }
    return opt, fs.Args(), -1
}

