    fmt.Fprintln(w, "  -cpuprofile string")
    fmt.Fprintln(w, "    \twrite CPU profile to this file")
    fmt.Fprintln(w, "  -debug string")
    fmt.Fprintln(w, "    \tdebug flags, any subset of \"fpstv\"")
    fmt.Fprintln(w, "  -diff")
    fmt.Fprintln(w, "    \twith -fix, don't update the files, but print a unified diff")
    fmt.Fprintln(w, "  -fix")
    fmt.Fprintln(w, "    \tapply all suggested fixes")
    fmt.Fprintln(w, "  -flags")
