    fmt.Fprintln(w, "  -memprofile string")
    fmt.Fprintln(w, "    \twrite memory profile to this file")
    fmt.Fprintln(w, "  -source")
    fmt.Fprintln(w, "    \tno effect (deprecated)")
    fmt.Fprintln(w, "  -tags string")
